from pathlib import Path
p=Path('/mnt/data/v17edit')
# frontend
f=p/'src/main/resources/static/index.html'; s=f.read_text()
# CSS
needle='.drink-size{display:block;font-size:.95rem;color:#64748b;font-weight:600;margin-top:3px}'
css=needle+'.finance-chart{display:flex;align-items:center;justify-content:center;gap:28px;flex-wrap:wrap}.pie{width:220px;height:220px;border-radius:50%;position:relative;display:grid;place-items:center}.pie::after{content:"";position:absolute;width:125px;height:125px;border-radius:50%;background:#fff}.pie-center{position:relative;z-index:1;text-align:center;font-weight:900;font-size:18px}.pie-center small{display:block;color:var(--muted);font-weight:700;font-size:12px}.finance-legend{display:grid;gap:12px;min-width:200px}.legend-row{display:flex;align-items:center;justify-content:space-between;gap:18px}.legend-dot{width:14px;height:14px;border-radius:50%;display:inline-block;margin-right:7px}.dot-income{background:#198754}.dot-expense{background:#dc3545}.registration-link{text-align:center;margin-top:12px}'
s=s.replace(needle,css)
# login markup
old='<div id="loginView" class="login"><div class="login-card"><div class="logo">🚒 FFH Verwaltung</div><p class="sub">Vereins- und Feuerwehrverwaltung</p><div class="field"><label>Benutzername</label><input id="loginUser" autocomplete="username"></div><div class="field"><label>Passwort</label><input id="loginPass" type="password" autocomplete="current-password"></div><button class="btn primary big" onclick="login()">Anmelden</button><div id="loginMsg"></div></div></div>'
new='<div id="loginView" class="login"><div class="login-card"><div class="logo">🚒 FFH Verwaltung</div><p class="sub">Vereins- und Feuerwehrverwaltung</p><div class="field"><label>Benutzername / E-Mail</label><input id="loginUser" autocomplete="username"></div><div class="field"><label>Passwort</label><input id="loginPass" type="password" autocomplete="current-password"></div><button class="btn primary big" onclick="login()">Anmelden</button><div id="loginMsg"></div><div class="registration-link"><button class="btn secondary" onclick="openRegistration()">Noch kein Zugang? Jetzt registrieren</button></div></div></div>'
s=s.replace(old,new)
# dashboard replace line
st=s.index('async function dashboard(){'); en=s.index('\nlet memberId=',st)
dash='''async function dashboard(){content.innerHTML=`<div class="title-row"><h1>Dashboard</h1><span class="sub">Aktuelle Übersicht</span></div><div class="cards"><div class="stat"><div class="label">Mitglieder</div><div class="value" id="sMembers">–</div></div><div class="stat"><div class="label">Aktive Mitglieder</div><div class="value" id="sActive">–</div></div><div class="stat"><div class="label">Kontostände gesamt</div><div class="value" id="sBalance">–</div></div><div class="stat"><div class="label">Getränke</div><div class="value" id="sDrinks">–</div></div><div class="stat"><div class="label">Angebotsartikel</div><div class="value" id="sOffers">–</div></div><div class="stat"><div class="label">Einnahmen diesen Monat</div><div class="value" id="sIncome">–</div></div><div class="stat"><div class="label">Ausgaben diesen Monat</div><div class="value" id="sExpenses">–</div></div><div class="stat"><div class="label">Saldo diesen Monat</div><div class="value" id="sFinanceBalance">–</div></div></div><div class="grid2"><div class="panel"><h3>Schnellzugriff</h3><div class="quick"><button class="btn primary big" onclick="navigate('theke')">🍺 Kasse öffnen</button><button class="btn secondary big" onclick="navigate('members')">👥 Mitglieder</button>${role==='ADMIN'?'<button class="btn secondary big" onclick="navigate(\\"inventory\\")">📋 Inventur</button>':''}</div></div><div class="panel"><h3>Finanzen – aktueller Monat</h3><div class="finance-chart"><div id="financePie" class="pie"><div class="pie-center"><span id="pieBalance">0,00 €</span><small>Saldo</small></div></div><div class="finance-legend"><div class="legend-row"><span><span class="legend-dot dot-income"></span>Einnahmen</span><strong id="pieIncome">0,00 €</strong></div><div class="legend-row"><span><span class="legend-dot dot-expense"></span>Ausgaben</span><strong id="pieExpenses">0,00 €</strong></div><div class="sub" id="financePeriod">–</div></div></div></div></div>`;try{if(['ADMIN','VORSTAND','KASSENWART','THEKE'].includes(role)){members=await api('/api/members');sMembers.textContent=members.length;sActive.textContent=members.filter(m=>m.active).length;sBalance.textContent=money(members.reduce((a,m)=>a+Number(m.balance||0),0))}else{sMembers.textContent='–';sActive.textContent='–';sBalance.textContent='–'}drinks=await api('/api/drinks');sDrinks.textContent=drinks.filter(d=>d.active).length;if(role==='ADMIN'){const shopping=await api('/api/inventory/shopping-list');sOffers.textContent=shopping.filter(x=>x.marktguruOffer!=null).length}else{sOffers.textContent='–'}if(['ADMIN','VORSTAND','KASSENWART'].includes(role)){const f=await api('/api/dashboard/finance');sIncome.textContent=money(f.income);sExpenses.textContent=money(f.expenses);sFinanceBalance.textContent=money(f.balance);financePeriod.textContent=`${f.from} bis ${f.to}`;pieIncome.textContent=money(f.income);pieExpenses.textContent=money(f.expenses);pieBalance.textContent=money(f.balance);const income=Math.max(0,Number(f.income||0)),expenses=Math.max(0,Number(f.expenses||0)),total=income+expenses;financePie.style.background=total?`conic-gradient(#198754 0deg ${(income/total)*360}deg,#dc3545 ${(income/total)*360}deg 360deg)`:'conic-gradient(#dfe4e8 0deg 360deg)'}else{sIncome.textContent='–';sExpenses.textContent='–';sFinanceBalance.textContent='–'}}catch{}}\n'''
s=s[:st]+dash+s[en:]
# registration before login
marker='async function login(){'
reg='''function openRegistration(){modalTitle.textContent='Mitglied registrieren';modalBody.innerHTML=`<div id="regMsg"></div><p class="sub">Die Registrierung wird erst nach Prüfung durch einen Administrator freigeschaltet.</p><div class="form-grid"><div class="field"><label>Vorname *</label><input id="regFirst" autocomplete="given-name"></div><div class="field"><label>Nachname *</label><input id="regLast" autocomplete="family-name"></div><div class="field full"><label>E-Mail *</label><input id="regEmail" type="email" autocomplete="email"></div><div class="field full"><label>Passwort *</label><input id="regPass" type="password" minlength="8" autocomplete="new-password"><small class="sub">Mindestens 8 Zeichen</small></div></div><div style="display:flex;justify-content:flex-end;gap:8px;margin-top:15px"><button class="btn secondary" onclick="closeModal()">Abbrechen</button><button class="btn primary" onclick="registerMember()">Registrieren</button></div>`;modal.classList.remove('hidden')}\nasync function registerMember(){const first=regFirst.value.trim(),last=regLast.value.trim(),email=regEmail.value.trim(),password=regPass.value;if(!first||!last||!email||password.length<8){regMsg.innerHTML='<div class="message error">Bitte Vorname, Nachname, E-Mail und ein Passwort mit mindestens 8 Zeichen eingeben.</div>';return}try{const r=await fetch('/api/auth/register',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({firstName:first,lastName:last,email,password})});if(!r.ok){let t='Registrierung fehlgeschlagen';try{const j=await r.json();t=j.message||j.error||t}catch{}throw Error(t)}const x=await r.json();closeModal();loginMsg.innerHTML='<div class="message success">✓ '+esc(x.message)+'</div>'}catch(e){regMsg.innerHTML='<div class="message error">'+esc(e.message)+'</div>'}}\n'''
s=s.replace(marker,reg+marker)
# admin function
st=s.index('async function adminPage()') if 'async function adminPage()' in s else s.index('function adminPage()')
en=s.index('\nfunction editAdminUser',st)
admin='''async function adminPage(){if(role!=='ADMIN'){content.innerHTML='<div class="panel"><h2>Keine Berechtigung</h2></div>';return}content.innerHTML='<div class="title-row"><div><h1>Administration</h1><span class="sub">Benutzer, Rollen und Registrierungsfreigaben</span></div></div><div class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>Benutzer</th><th>Mitglied</th><th>E-Mail</th><th>Rolle</th><th>Status</th><th>Aktion</th></tr></thead><tbody id="userRows"></tbody></table></div></div>';try{const us=await api('/api/admin/users');window.adminUsers=us;userRows.innerHTML=us.map(u=>{const pending=!u.registrationApproved;return `<tr><td><strong>${esc(u.username)}</strong></td><td>${esc(u.memberName||'–')}</td><td>${esc(u.email||'–')}</td><td>${esc(roleLabels[u.role]||u.role)}</td><td>${pending?'<span class="badge">Freigabe ausstehend</span>':`<span class="badge ${u.enabled?'ok':'off'}">${u.enabled?'Aktiv':'Deaktiviert'}</span>`}</td><td>${pending?`<button class="btn small primary" onclick="approveRegistration(${u.id})">Freigeben</button> `:''}<button class="btn small secondary" onclick="editAdminUser(${u.id})">Bearbeiten</button></td></tr>`}).join('')||'<tr><td colspan="6" class="empty">Keine Benutzer vorhanden.</td></tr>'}catch(e){userRows.innerHTML=`<tr><td colspan="6" class="empty">${esc(e.message)}</td></tr>`}}\nasync function approveRegistration(id){try{await api(`/api/admin/users/${id}/approve`,{method:'POST'});adminPage()}catch(e){alert(e.message)}}'''
s=s[:st]+admin+s[en:]
f.write_text(s)
